(3077200, 426873, 41337, '<td valign="top">This has a much more sinster look to it than the other version I''ve seen of this. Very good.</td>', 'This has a much more sinster look to it than the other version I''ve seen of this. Very good.', '2006-12-01 00:09:44.000000', NULL, 1),
(3077201, 424878, 31637, '<td valign="top">nice work</td>', 'nice work', '2006-12-01 00:09:45.000000', NULL, 1),
(3077203, 433489, 15711, '<td valign="top">Stunning vista.  I can hear the water lapping up on the shore. The blue theme adds a wintery touch to it. This would be great for the HDR treatment!</td>', 'Stunning vista.  I can hear the water lapping up on the shore. The blue theme adds a wintery touch to it. This would be great for the HDR treatment!', '2006-12-01 00:10:07.000000', NULL, 1),
(3077204, 433269, 31637, '<td valign="top">ultra clear</td>', 'ultra clear', '2006-12-01 00:10:07.000000', NULL, 1),
