(3081273, 432119, 34192, '<td valign="top">very serene.  I like how it all comes together at the tree.</td>', 'very serene.  I like how it all comes together at the tree.', '2006-12-02 09:03:30.000000', NULL, 1),
(3081274, 428183, 34192, '<td valign="top">really like this.  A lot of dead space on the left which makes the image seem slightly unbalanced.  Still trying to decide if that matters or not.</td>', 'really like this.  A lot of dead space on the left which makes the image seem slightly unbalanced.  Still trying to decide if that matters or not.', '2006-12-02 09:04:45.000000', NULL, 1),
(3081275, 424642, 34192, '<td valign="top">very pretty.  Like the inclusion of the people to give it context.</td>', 'very pretty.  Like the inclusion of the people to give it context.', '2006-12-02 09:05:24.000000', NULL, 1),
