(3081738, 426108, 65603, '<td valign="top">Nice capture!! Just a little to whitewashed. Very beautiful shot though.</td>', 'Nice capture!! Just a little to whitewashed. Very beautiful shot though.', '2006-12-02 13:46:08.000000', NULL, 1),
(3081742, 433306, 30982, '<td valign="top">I really like the way this is presented with only the half faces of the younger women.</td>', 'I really like the way this is presented with only the half faces of the younger women.', '2006-12-02 13:47:35.000000', NULL, 1),
(3081744, 433117, 65603, '<td valign="top">Too dark I did not see the man on the tractor at first glance. The browns all run together making the "darkness" overwhelm the shot.</td>', 'Too dark I did not see the man on the tractor at first glance. The browns all run together making the "darkness" overwhelm the shot.', '2006-12-02 13:48:39.000000', NULL, 1),
