INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3082118, 430404, 24613, '<td valign="top">Very fitting title.  Nice work! 9</td>', 'Very fitting title.  Nice work! 9', '2006-12-02 18:09:34.000000', NULL, 1),
(3082132, 430164, 24613, '<td valign="top">This shot has a wonderful, fairyland feel to it.  Great work!</td>', 'This shot has a wonderful, fairyland feel to it.  Great work!', '2006-12-02 18:22:23.000000', NULL, 1),
(3082134, 421647, 24613, '<td valign="top">Too cool!  Love the DOF. 9</td>', 'Too cool!  Love the DOF. 9', '2006-12-02 18:23:22.000000', NULL, 1),
(3082138, 433533, 24613, '<td valign="top">I love lighthouses and this is my favorite in the world!!  My shots of it pale in quality to this one! Fantastic shot of the toughest, stubbyist little lighthouse in the world.  I''m hoping to return to RI soon and the Narragansett bay will be on my list of photo shoots! 10</td>', 'I love lighthouses and this is my favorite in the world!!  My shots of it pale in quality to this one! Fantastic shot of the toughest, stubbyist little lighthouse in the world.  I''m hoping to return to RI soon and the Narragansett bay will be on my list of photo shoots! 10', '2006-12-02 18:25:12.000000', NULL, 1),
(3082185, 426873, 66267, '<td valign="top">heyy another great photo, even better than your "posion" one!</td>', 'heyy another great photo, even better than your "posion" one!', '2006-12-02 18:47:46.000000', NULL, 1),
(3082276, 431682, 53243, '<td valign="top">a very nice action shot</td>', 'a very nice action shot', '2006-12-02 19:37:23.000000', NULL, 1),
