(3086765, 433250, 30982, '<td valign="top">Neat!  Well seen.</td>', 'Neat!  Well seen.', '2006-12-04 14:48:57.000000', NULL, 1),
(3086766, 433538, 64929, '<td valign="top">The water ripples makes this one for me - well done!  Great composition &amp; clarity *bump*</td>', 'The water ripples makes this one for me - well done!  Great composition & clarity *bump*', '2006-12-04 14:49:09.000000', NULL, 1),
