(3093068, 433246, 30982, '<td valign="top">Has a kind of painterly-otherworldy feel to it.</td>', 'Has a kind of painterly-otherworldy feel to it.', '2006-12-06 14:01:28.000000', NULL, 1),
(3093069, 433017, 39993, '<td valign="top">Great capture.</td>', 'Great capture.', '2006-12-06 14:01:31.000000', NULL, 1),
(3093070, 433479, 30982, '<td valign="top">What a delightful, joyous picture!  I love the look of determination on his face.</td>', 'What a delightful, joyous picture!  I love the look of determination on his face.', '2006-12-06 14:02:04.000000', NULL, 1),
(3093071, 430033, 30982, '<td valign="top">Bit of a drought?  Nicely seen.</td>', 'Bit of a drought?  Nicely seen.', '2006-12-06 14:02:25.000000', NULL, 1),
