INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3250126, 426217, 68504, '<td valign="top">Really works for me.  Been by this photo several times and I wonder why it should be so striking, maybe it is more than just the essence of the 40''s, or maybe the essence of the 40''s was significant, the generation of woman who took on tough war time jobs and responsibilities, for whom there was no looking back... Maybe she should replace FDR on the American dime (whose profile was modeled by a female sculptor), and FDR replaced the Statue of Liberty, all a grand tradition. (That''s my ten cents).</td>', 'Really works for me.  Been by this photo several times and I wonder why it should be so striking, maybe it is more than just the essence of the 40''s, or maybe the essence of the 40''s was significant, the generation of woman who took on tough war time jobs and responsibilities, for whom there was no looking back... Maybe she should replace FDR on the American dime (whose profile was modeled by a female sculptor), and FDR replaced the Statue of Liberty, all a grand tradition. (That''s my ten cents).', '2007-01-18 02:50:43.000000', NULL, 0),
